#include <bits/stdc++.h>
using namespace std;
// Removing a node never changes whether any other node qualifies (its children inherit a parent
// they also disrespect), so the answer is every qualifying node in increasing order: O(n).
int main(){ ios::sync_with_stdio(false); cin.tie(nullptr);
  int n; cin >> n; vector<int> p(n + 1), c(n + 1); vector<bool> ok(n + 1, true);
  for(int i = 1; i <= n; i++){ cin >> p[i] >> c[i]; if(c[i] == 0) ok[i] = false; }
  for(int i = 1; i <= n; i++) if(p[i] != -1 && c[i] == 0) ok[p[i]] = false;
  vector<int> out; for(int i = 1; i <= n; i++) if(p[i] != -1 && ok[i]) out.push_back(i);
  if(out.empty()) cout << -1; else for(size_t i = 0; i < out.size(); i++) cout << out[i] << (i + 1 < out.size() ? " " : "");
  cout << "\n"; }

